CREATE TABLE IF NOT EXISTS `system_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `config_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `config_value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKnpsxm1erd0lbetjn5d3ayrsof` (`config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `users` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `avatar_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `full_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` bit(1) DEFAULT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('ADMIN','MANAGER','STAFF') COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKr43af9ap4edm43mmtq01oddj6` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_source_tables` (source_book varchar(30) NOT NULL, sheet_name varchar(100) NOT NULL, spreadsheet_id varchar(100) NOT NULL, source_range varchar(200) NOT NULL, header_json JSON NOT NULL, source_row_count int NOT NULL, PRIMARY KEY(source_book,sheet_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_source_rows` (source_book varchar(30) NOT NULL, sheet_name varchar(100) NOT NULL, sheet_row int NOT NULL, row_json JSON NOT NULL, PRIMARY KEY(source_book,sheet_name,sheet_row)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_sales` (transaction_id varchar(100) NOT NULL PRIMARY KEY, serial_key varchar(100), matched_cycle_id varchar(50), sold_at datetime(6), customer_name varchar(200), customer_phone varchar(50), status varchar(50), payment_status varchar(50), list_price decimal(15,0), discount decimal(15,0), final_price decimal(15,0), source_kind varchar(30) NOT NULL, web_sale_json JSON, datasale_json JSON) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_catalog_map` (source_kind varchar(30) NOT NULL, source_id varchar(50) NOT NULL, target_id varchar(50) NOT NULL, detail_json JSON NOT NULL, PRIMARY KEY(source_kind,source_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_cycle_metadata` (cycle_id varchar(50) NOT NULL PRIMARY KEY, serial_key varchar(100) NOT NULL, source_model_id varchar(50), source_variant_id varchar(50), lifecycle_kind varchar(10) NOT NULL, metadata_json JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `qk_migration_manifest` (snapshot_id varchar(100) NOT NULL PRIMARY KEY, asof_date date NOT NULL, source_captured_at datetime(6) NOT NULL, base_commit varchar(40) NOT NULL, source_sha256 varchar(64) NOT NULL, status varchar(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;

